def _json_content(json: Any, method: str) -> bytes | None:
    """`json` encoded as the body of a `method` request, or None for no body.

    The encoding is httpx2's: UTF-8, no spaces, and no NaN or infinity.

    Raises:
        InvalidRequestError: `json` goes with a GET or HEAD, or cannot be
            encoded as JSON (`invalid_argument`).
    """
    if json is None:
        return None
    if method in ("GET", "HEAD"):
        raise client_error(
            INVALID_ARGUMENT, f"A {method} request carries no body; drop json"
        )
    try:
        text = jsonlib.dumps(
            json, ensure_ascii=False, separators=(",", ":"), allow_nan=False
        )
        return text.encode()
    except (TypeError, ValueError, RecursionError) as error:
        raise client_error(
            INVALID_ARGUMENT, f"The request's json is not JSON: {error}"
        ) from error


def retry_after(response: httpx2.Response) -> float | None:
    """Return the wait a `Retry-After` header asks for, in seconds, or None.

    The value is ASCII digits, a count of seconds, or an IMF-fixdate such as
    `Sun, 06 Nov 1994 08:49:37 GMT`, of which a past date asks for 0. Any other
    value asks for nothing, and the caller backs off on its own.
    """
    value = response.headers.get("retry-after", "").strip()
    if _SECONDS.fullmatch(value):
        return float(value)
    if not _IMF_FIXDATE.fullmatch(value):
        return None
    try:
        moment = parsedate_to_datetime(value)
    except ValueError:
        return None
    return max(0.0, (moment - datetime.now(UTC)).total_seconds())


# The clock and the reading the attempt in flight must end by, or None when it
# has no deadline. `_DeadlineBackend` reads it at each network operation.
_ATTEMPT: ContextVar[tuple[Clock, float] | None] = ContextVar(
    "dfo_attempt", default=None
)


@contextmanager
def attempt_deadline(clock: Clock, deadline: float | None) -> Generator[None]:
    """Bound post-resolution network operations inside the block to `deadline`."""
    token = _ATTEMPT.set(None if deadline is None else (clock, deadline))
    try:
        yield
    finally:
        _ATTEMPT.reset(token)


def _time_left(timeout: float | None, expired: type[Exception]) -> float | None:
    """Return `timeout` clamped to the time left on the attempt in flight.

    Raises:
        Exception: An `expired` timeout, once the attempt's deadline has passed.
    """
    bound = _ATTEMPT.get()
    if bound is None:
        return timeout
    clock, deadline = bound
    left = deadline - clock()
    if left <= 0:
        raise expired("The attempt's deadline passed")
    return left if timeout is None else min(timeout, left)


def _read_within(response: httpx2.Response, limit: int) -> bool:
    """Read `response`'s body as it decodes, and return whether it fit in `limit`
    bytes. Reading stops once the body passes `limit`, and the response keeps an
    empty body.

    httpx2 decodes a compressed body in pieces of at most 1 MiB, so at most one
    piece past `limit` is held before reading stops.
    """
    pieces = []
    size = 0
    for piece in response.iter_bytes():
        size += len(piece)
        if size > limit:
            response._content = b""
            return False
        pieces.append(piece)
    # As `Response.read` keeps the body it reads.
    response._content = b"".join(pieces)
    return True


